    Handles strings with escapes, numbers, booleans, null, arrays, and objects.
    """
    index = 0

    def parse_value():
        nonlocal index
        while index < len(s) and s[index].isspace():
            index += 1
        if index >= len(s):
            raise ValueError("Unexpected end of input")

        char = s[index]

        if char == '"':
            return parse_string()
        elif char.isdigit() or (char == '-' and s[index + 1].isdigit()):
            return parse_number()
        elif s.startswith('true', index):
            index += 4
            return True
        elif s.startswith('false', index):
            index += 5
            return False
        elif s.startswith('null', index):
            index += 4
            return None
        elif char == '[':
            return parse_array()
        elif char == '{':
            return parse_object()
        else:
            raise ValueError(f"Unexpected character: {char}")

    def parse_string():
        nonlocal index
        index += 1  # Skip opening quote
        result = []
        while index < len(s):
            char = s[index]
            if char == '"':
                index += 1  # Skip closing quote
                return ''.join(result)
            elif char == '\\':
                index += 1
                escape_char = s[index]
                if escape_char == 'n':
                    result.append('\n')
                elif escape_char == 't':
                    result.append('\t')
                elif escape_char == 'r':
                    result.append('\r')
