        arr = []
        while True:
            while index < len(s) and s[index].isspace():
                index += 1
            if index < len(s) and s[index] == ']':
                index += 1  # Skip closing bracket
                return arr
            value = parse_value()
            arr.append(value)
            while index < len(s) and s[index].isspace():
                index += 1
            if index < len(s) and s[index] == ']':
                index += 1  # Skip closing bracket
                return arr
            if index < len(s) and s[index] == ',':
                index += 1  # Skip comma
            else:
                raise ValueError("Expected ',' or ']' in array")

    def parse_object():
        nonlocal index
        index += 1  # Skip opening brace
        obj = {}
        while True:
            while index < len(s) and s[index].isspace():
                index += 1
            if index < len(s) and s[index] == '}':
                index += 1  # Skip closing brace
                return obj
