def parse_json(s: str) -> object:
    """Parse a JSON string into Python objects using a state machine approach."""

    class Parser:
        def __init__(self, s):
            self.s = s
            self.pos = 0
            self.current_char = s[self.pos] if s else None

        def error(self):
            raise ValueError("Invalid JSON string")

        def advance(self):
            self.pos += 1
            if self.pos < len(self.s):
                self.current_char = self.s[self.pos]
            else:
                self.current_char = None

        def skip_whitespace(self):
            while self.current_char is not None and self.current_char.isspace():
                self.advance()

        def parse_value(self):
            self.skip_whitespace()
            if self.current_char == '"':
                return self.parse_string()
            elif self.current_char == '{':
                return self.parse_object()
            elif self.current_char == '[':
                return self.parse_array()
            elif self.current_char in "-0123456789":
                return self.parse_number()
            elif self.current_char == 't':
                return self.parse_true()
            elif self.current_char == 'f':
                return self.parse_false()
            elif self.current_char == 'n':
                return self.parse_null()
            else:
                self.error()

        def parse_string(self):
            result = ''
            self.advance()  # Skip opening quote
            while self.current_char is not None:
                if self.current_char == '"':
                    self.advance()  # Skip closing quote
                    return result
                elif self.current_char == '\\':
                    self.advance()  # Skip backslash
                    if self.current_char == 'n':
                        result += '\n'
                    elif self.current_char == 't':
                        result += '\t'
                    elif self.current_char == '\\':
                        result += '\\'
                    elif self.current_char == '"':
                        result += '"'
                    else:
                        self.error()
                else:
                    result += self.current_char
                self.advance()
            self.error()

        def parse_number(self):
            number_str = ''
            while self.current_char is not None and (self.current_char.isdigit() or self.current_char in '.-'):
                number_str += self.current_char
                self.advance()
            if '.' in number_str:
                return float(number_str)
            return int(number_str)

        def parse_object(self):
            self.advance()  # Skip opening brace
            obj = {}
            self.skip_whitespace()
            while self.current_char is not None and self.current_char != '}':
                key = self.parse_string()
                self.skip_whitespace()
                if self.current_char != ':':
                    self.error()
                self.advance()  # Skip colon
                value = self.parse_value()
                obj[key] = value
                self.skip_whitespace()
                if self.current_char == ',':
                    self.advance()  # Skip comma
                elif self.current_char != '}':
                    self.error()
            self.advance()  # Skip closing brace
            return obj

        def parse_array(self):
            self.advance()  # Skip opening bracket
            arr = []
            self.skip_whitespace()
            while self.current_char is not None and self.current_char != ']':
                value = self.parse_value()
                arr.append(value)
                self.skip_whitespace()
                if self.current_char == ',':
                    self.advance()  # Skip comma
                elif self.current_char != ']':
                    self.error()
            self.advance()  # Skip closing bracket
            return arr

        def parse_true(self):
            self.advance()  # Skip 't'
            if self.current_char == 'r':
                self.advance()  # Skip 'r'
                if self.current_char == 'u':
                    self.advance()  # Skip 'u'
                    if self.current_char == 'e':
                        self.advance()  # Skip 'e'
                        return True
            self.error()

        def parse_false(self):
            self.advance()  # Skip 'f'
            if self.current_char == 'a':
                self.advance()  # Skip 'a'
                if self.current_char == 'l':
                    self.advance()  # Skip 'l'
                    if self.current_char == 's':
                        self.advance()  # Skip 's'
                        if self.current_char == 'e':
                            self.advance()  # Skip 'e'
                            return False
            self.error()

        def parse_null(self):
            self.advance()  # Skip 'n'
            if self.current_char == 'u':
                self.advance()  # Skip 'u'
                if self.current_char == 'l':
                    self.advance()  # Skip 'l'
                    if self.current_char == 'l':
                        self.advance()  # Skip 'l'
                        return None
            self.error()

    parser = Parser(s)
    return parser.parse_value()

def parse_json(s: str) -> object:
    """
    Simple recursive descent parser for a JSON-like string.
    This function handles strings, numbers, booleans, null, arrays, and objects.
    """

    index = 0

    def parse_value():
        nonlocal index
        skip_whitespace()
        if index >= len(s):
            raise ValueError("Unexpected end of input")

        char = s[index]
        if char == '"':
            return parse_string()
        elif char.isdigit() or char in '-':
            return parse_number()
        elif s.startswith('true', index):
            index += 4
            return True
        elif s.startswith('false', index):
            index += 5
            return False
        elif s.startswith('null', index):
            index += 4
            return None
        elif char == '[':
            return parse_array()
        elif char == '{':
            return parse_object()
        else:
            raise ValueError(f"Invalid JSON value at index {index}: {char}")

    def skip_whitespace():
        nonlocal index
        while index < len(s) and s[index] in ' \n\t\r':
            index += 1

    def parse_string():
        nonlocal index
        index += 1  # Skip the opening quote
        start_index = index
        while index < len(s):
            if s[index] == '"':
                result = s[start_index:index]
                index += 1  # Skip the closing quote
                return unescape_string(result)
            elif s[index] == '\\':
                index += 1  # Skip the backslash
            index += 1
        raise ValueError("Unterminated string")

    def unescape_string(s):
        escape_sequences = {
            'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t', '"': '"', '\\': '\\'
        }
        result = []
        i = 0
        while i < len(s):
            if s[i] == '\\':
                i += 1
                if i < len(s) and s[i] in escape_sequences:
                    result.append(escape_sequences[s[i]])
                else:
                    raise ValueError(f"Invalid escape sequence: \\{s[i]}")
            else:
                result.append(s[i])
            i += 1
        return ''.join(result)

    def parse_number():
        nonlocal index
        start_index = index
        if s[index] == '-':
            index += 1
        if index < len(s) and s[index] == '0':
            index += 1
        else:
            while index < len(s) and s[index].isdigit():
                index += 1
        if index < len(s) and s[index] == '.':
            index += 1
            if index < len(s) and s[index].isdigit():
                while index < len(s) and s[index].isdigit():
                    index += 1
        if index < len(s) and (s[index] == 'e' or s[index] == 'E'):
            index += 1
            if index < len(s) and (s[index] == '-' or s[index] == '+'):
                index += 1
            if index >= len(s) or not s[index].isdigit():
                raise ValueError("Invalid number format")
            while index < len(s) and s[index].isdigit():
                index += 1
        return float(s[start_index:index]) if '.' in s[start_index:index] else int(s[start_index:index])

    def parse_array():
        nonlocal index
        index += 1  # Skip the opening '['
        result = []
        skip_whitespace()
        if s[index] == ']':
            index += 1
            return result
        while True:
            result.append(parse_value())
            skip_whitespace()
            if s[index] == ']':
                index += 1
                return result
            elif s[index] != ',':
                raise ValueError("Expected ',' or ']' in array")
            index += 1
            skip_whitespace()

    def parse_object():
        nonlocal index
        index += 1  # Skip the opening '{'
        result = {}
        skip_whitespace()
        if s[index] == '}':
            index += 1
            return result
        while True:
            key = parse_string()
            skip_whitespace()
            if s[index] != ':':
                raise ValueError("Expected ':' in object")
            index += 1
            value = parse_value()
            result[key] = value
            skip_whitespace()
            if s[index] == '}':
                index += 1
                return result
            elif s[index] != ',':
                raise ValueError("Expected ',' or '}' in object")
            index += 1
            skip_whitespace()

    return parse_value()

