def parse_json(s: str) -> object:
    """
    Parses a JSON string into Python objects using a recursive descent parser technique.
    This function handles strings (with escapes), numbers, booleans, null, arrays, and objects.
    """

    def parse_value(index: int):
        nonlocal s
        if s[index] == '"':
            return parse_string(index)
        elif s[index].isdigit() or s[index] == '-':
            return parse_number(index)
        elif s[index:index + 4] == 'true':
            return True, index + 4
        elif s[index:index + 5] == 'false':
            return False, index + 5
        elif s[index:index + 4] == 'null':
            return None, index + 4
        elif s[index] == '[':
            return parse_array(index)
        elif s[index] == '{':
            return parse_object(index)
        raise ValueError("Invalid JSON input")

    def parse_string(index: int):
        end_index = index + 1
        while end_index < len(s):
            if s[end_index] == '"' and s[end_index - 1] != '\\':
                break
            if s[end_index] == '\\':
                end_index += 1  # Skip escaped character
            end_index += 1
        return s[index + 1:end_index].encode().decode('unicode-escape'), end_index + 1

    def parse_number(index: int):
        end_index = index
        while end_index < len(s) and (s[end_index].isdigit() or s[end_index] in ['-', '+', '.', 'e', 'E']):
            end_index += 1
        number = s[index:end_index]
        if '.' in number or 'e' in number or 'E' in number:
            return float(number), end_index
        return int(number), end_index

    def parse_array(index: int):
        array = []
        index += 1  # Skip the opening '['
        while index < len(s):
            if s[index] == ']':
                return array, index + 1
            value, index = parse_value(index)
            array.append(value)
            if s[index] == ',':
                index += 1
            elif s[index] == ']':
                return array, index + 1
            else:
                raise ValueError("Invalid JSON array syntax")
        raise ValueError("Unexpected end of JSON array")

    def parse_object(index: int):
        obj = {}
        index += 1  # Skip the opening '{'
        while index < len(s):
            if s[index] == '}':
                return obj, index + 1
            key, index = parse_string(index)
            if s[index] != ':':
                raise ValueError("Invalid JSON object syntax")
            index += 1  # Skip ':'
            value, index = parse_value(index)
            obj[key] = value
            if s[index] == ',':
                index += 1
            elif s[index] == '}':
                return obj, index + 1
            else:
                raise ValueError("Invalid JSON object syntax")
        raise ValueError("Unexpected end of JSON object")

    result, index = parse_value(0)
    if index != len(s):
        raise ValueError("Excess characters after JSON input")
    return result
